package com.restaurant.pos.config;
import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.web.SecurityFilterChain; import org.springframework.core.convert.converter.Converter; import org.springframework.security.oauth2.server.resource.authentication.*; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.security.core.authority.SimpleGrantedAuthority; import java.util.*;
@Configuration @EnableMethodSecurity public class SecurityConfig {
 @Bean SecurityFilterChain security(HttpSecurity h) throws Exception { return h.csrf(c->c.disable()).authorizeHttpRequests(a->a.requestMatchers("/","/index.html","/*.js","/*.css","/assets/**","/actuator/health").permitAll().anyRequest().authenticated()).oauth2ResourceServer(o->o.jwt(j->j.jwtAuthenticationConverter(converter()))).build(); }
 private Converter<Jwt, JwtAuthenticationToken> converter(){ return jwt->{ var roles=new ArrayList<SimpleGrantedAuthority>(); Object realm=jwt.getClaim("realm_access"); if(realm instanceof Map<?,?> m && m.get("roles") instanceof Collection<?> rs) rs.forEach(r->roles.add(new SimpleGrantedAuthority("ROLE_"+r))); return new JwtAuthenticationToken(jwt,roles,jwt.getClaimAsString("preferred_username"));}; }
}
